import{_ as e,o as s,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Historial","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/history.md","filePath":"es-ES/user-guide/settings/history.md","lastUpdated":1789222057000}'),i={name:"es-ES/user-guide/settings/history.md"};function t(n,a,l,d,c,u){return s(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="historial" tabindex="-1">Historial <a class="header-anchor" href="#historial" aria-label="Permalink to &quot;Historial&quot;">​</a></h1><p>La página de Historial gestiona los registros de uso y las prioridades de reapertura adaptativa. Contiene dos pestañas: <strong>Historial de búsqueda</strong> e <strong>Historial de palabras clave</strong>.</p><h2 id="_1-historial-de-busqueda" tabindex="-1">1. Historial de búsqueda <a class="header-anchor" href="#_1-historial-de-busqueda" aria-label="Permalink to &quot;1. Historial de búsqueda&quot;">​</a></h2><p>Registra los resultados ejecutados asociando el término de búsqueda con la ruta física del elemento:</p><ul><li><strong>Reapertura adaptativa priorizada</strong>: Al escribir caracteres similares a consultas anteriores, Lertaro prioriza los elementos abiertos previamente en la parte superior. Por ejemplo, si abriste <code>BCompare.exe</code> buscando <code>bcomp</code>, una búsqueda futura de <code>bc</code> lo destacará al inicio.</li><li><strong>Orden según el uso</strong>: Dentro de las coincidencias del historial, Lertaro ordena por posición inicial de la coincidencia, número de usos descendente, apertura más reciente descendente y peso de coincidencia difusa, en ese orden. Solo afecta a los candidatos del historial; las demás categorías conservan su ordenación.</li><li><strong>Agrupación en la Ventana incrustada</strong>: En los diálogos de archivos, las coincidencias del historial dentro de la carpeta activa se clasifican en &quot;Carpeta actual&quot; y las demás en &quot;Búsqueda global&quot;.</li><li><strong>Filtrado de rutas inexistentes</strong>: Si un archivo ha sido eliminado o movido externamente, se omite de forma automática, evitando enlaces rotos y resultados duplicados.</li><li><strong>Opciones de gestión</strong>: <ul><li><strong>Habilitar historial</strong>: Interruptor general; al desactivarlo se conservan los registros existentes. No se añaden entradas nuevas, pero volver a abrir una entrada existente sigue incrementando su contador de usos.</li><li><strong>Filtro de búsqueda</strong>: Permite filtrar las entradas visibles.</li><li><strong>Contadores y limpieza</strong>: Cada entrada muestra cuántas veces se ha abierto. Elige un umbral y pulsa <strong>Borrar con como máximo N usos</strong> para eliminar entradas poco utilizadas; también puedes eliminar filas individuales o pulsar <strong>Borrar todo el historial</strong>.</li><li><strong>Actualización en tiempo real</strong>: La lista actualiza automáticamente los contadores cuando otra ventana de búsqueda registra una nueva apertura.</li></ul></li></ul><h2 id="_2-historial-de-palabras-clave" tabindex="-1">2. Historial de palabras clave <a class="header-anchor" href="#_2-historial-de-palabras-clave" aria-label="Permalink to &quot;2. Historial de palabras clave&quot;">​</a></h2><p>Memoriza las <strong>cadenas de búsqueda originales</strong> que se hayan usado realmente para ejecutar un resultado o una acción, o para abrir la Ventana principal. Escribir una consulta y cerrar o abandonar la Ventana rápida no la añade:</p><ul><li><strong>Navegación por atajos</strong>: En la Ventana rápida, pulsa <strong><code>Alt+Up</code></strong> / <strong><code>Alt+Down</code></strong> para retroceder o avanzar entre consultas recientes. Pulsa <strong><code>Ctrl+Delete</code></strong> para borrar el término activo.</li><li><strong>Contadores y limpieza</strong>: Cada palabra clave muestra cuántas veces se ha usado. Elige un umbral y pulsa <strong>Borrar con como máximo N usos</strong> para eliminar palabras clave poco utilizadas.</li><li><strong>Gestión independiente</strong>: Dispone de su propio interruptor de activación, filtro, eliminación individual y botón de <strong>Borrar todo el historial</strong>. Aunque esté desactivado, las palabras clave existentes siguen acumulando usos y las nuevas no se añaden.</li></ul>',8)])])}const m=e(i,[["render",t]]);export{g as __pageData,m as default};
